NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Lamentations'

CHAPTERS = {
    1: {
        1: 'Kako mesto sedi osamljeno, ki je bilo polno ljudstva! Kako je ona postala kakor vdova! Ona, ki je bila velika med narodi in princesa med provincami, kako je postala podvržena davku!',
        2: 'Bridko joka ponoči in njene solze so na njenih licih. Med vsemi svojimi ljubimci nima nikogar, da jo potolaži. Vsi njeni prijatelji so zahrbtno postopali z njo, postali so njeni sovražniki.',
        3: 'Juda je odšel v ujetništvo zaradi stiske in zaradi velikega hlapčevstva. Prebiva med pogani, ne najde nobenega počitka. Vsi njegovi preganjalci so ga dohiteli med ožinami.',
        4: 'Poti [na] Sion žalujejo, ker ni nihče prišel k slovesnim praznikom. Vsa njena velika vrata so zapuščena. Njeni duhovniki vzdihujejo, njene device so užaloščene in sama je v grenkobi.',
        5: 'Njeni nasprotniki so vodilni, njeni sovražniki uspevajo; kajti Gospod jo je prizadel zaradi množice njenih prestopkov. Njeni otroci so odšli v ujetništvo pred sovražnikom.',
        6: 'Od sionske hčere je odšla vsa njena lepota. Njeni princi so postali podobni jelenom, ki ne najdejo pašnika in odšli so brez moči pred zasledovalcem.',
        7: 'V dneh svoje stiske in svojih bed se je [prestolnica] Jeruzalem spomnila vseh svojih prijetnih stvari, ki jih je imela v dneh davnine, ko je njeno ljudstvo padlo v roko sovražnika in ji nihče ni pomagal. Nasprotniki so jo videli in jo zasmehovali pri njenih šabatih.',
        8: '[Prestolnica] Jeruzalem je bridko grešila, zato je odstranjena. Vsi, ki so jo častili, jo prezirajo, ker so videli njeno nagoto. Da, ona vzdihuje in se obrača nazaj.',
        9: 'Njena umazanost je v krajcih njenih oblačil; ne spominja se svojega zadnjega konca, zato se je čudovito spustila. Nobenega tolažnika ni imela. Oh Gospod, glej mojo stisko, kajti sovražnik se je poveličal.',
        10: 'Nasprotnik je svojo roko razprostrl nad vse njene prijetne stvari, kajti videla je, da so pogani vstopili v njeno svetišče, katerim si zapovedal, da naj ne vstopijo v tvojo skupnost.',
        11: 'Vse njeno ljudstvo vzdihuje, iščejo kruh; svoje prijetne stvari so dali za hrano, da podprejo dušo. Glej, oh Gospod in preudari, kajti postala sem ničvredna.',
        12: 'Ali vam ni to nič, vsi vi, ki greste mimo? Glejte in vidite, če je tam kakršnakoli bridkost podobna moji bridkosti, ki mi je storjena, s katero me je Gospod prizadel na dan svoje krute jeze.',
        13: 'Od zgoraj je poslal ogenj v moje kosti in ta je prevladal zoper njih. Razprostrl je mrežo za moja stopala, obrnil me je nazaj. Naredil me je zapuščeno in ves dan slabim.',
        14: 'Jarem mojih prestopkov je zvezan z njegovo roko. Oviti so in prišli so gor nad moj vrat. Moji moči je storil, da odpove, Gospod me je izročil v njihove roke, pred katerimi se nisem zmožen dvigniti.',
        15: 'Gospod je pod stopalom pomendral vse moje mogočne može v moji sredi. Zoper mene je sklical zbor, da zdrobi moje mladeniče. Gospod je pomendral devico, Judovo hčer, kakor v vinski stiskalnici.',
        16: 'Zaradi teh stvari jokam. Moje oko, moje oko teče dol z vodo, ker je tolažnik, ki naj bi razbremenil mojo dušo, daleč od mene. Moji otroci so zapuščeni, ker je sovražnik prevladal.',
        17: 'Sion razširja svoje roke in tam ni nikogar, da jo potolaži. Gospod je zapovedal glede Jakoba, da naj bi bili njegovi nasprotniki naokoli njega. [Prestolnica] Jeruzalem je med njimi kakor ženska, ki ima menstruacijo.',
        18: 'Gospod je pravičen, kajti uprla sem se zoper njegovo zapoved. Poslušajte, prosim vas, vsa ljudstva in glejte mojo bridkost. Moje device in moji mladeniči so odšli v ujetništvo.',
        19: 'Poklicala sem svoje ljubimce, toda oni so me zavedli. Moji duhovniki in moje starešine so v mestu izročili duha, medtem ko so iskali svojo hrano, da podprejo svoje duše.',
        20: 'Glej, oh Gospod, kajti v tegobi sem. Moja notranjost je nemirna; moje srce je obrnjeno znotraj mene; kajti neposlušno sem se uprla. Zunaj ropa meč, doma je kakor smrt.',
        21: 'Slišali so, da sem zavzdihnila. Tam ni nikogar, da me potolaži. Vsi moji sovražniki so slišali o moji stiski; veseli so, da si to storil. Privedel boš dan, ki si ga poklical in oni bodo podobni meni.',
        22: 'Naj vsa njihova zlobnost pride predte, in stori jim, kakor si storil meni, zaradi vseh mojih prestopkov, kajti mojih vzdihov je mnogo in moje srce je oslabelo.',
    },
    2: {
        1: 'Kako je Gospod v svoji jezi pokril sionsko hčer z oblakom in vrgel dol z neba na zemljo Izraelovo lepoto in se ni spominjal svoje pručke na dan svoje jeze!',
        2: 'Gospod je požrl vsa Jakobova prebivališča in se ni usmilil. V svojem besu je zrušil oporišča Judove hčere; privedel jih je dol do tal. Oskrunil je kraljestvo in njegove prince.',
        3: 'V svoji kruti jezi je odrezal ves Izraelov rog. Svojo desnico je umaknil izpred sovražnika in zoper Jakoba je gorel plameneč ogenj, ki požira vsenaokrog.',
        4: 'Svoj lok je upognil kakor sovražnik. S svojo desnico je stal kakor nasprotnik in usmrtil vse, ki so bili prijetni za oko v šotorskem svetišču sionske hčere. Svojo razjarjenost je izlil kakor ogenj.',
        5: 'Gospod je bil kakor sovražnik. Požrl je Izraela, požrl je vse njegove palače. Uničil je vsa njegova oporišča in v Judovi hčeri je povečal žalovanje in objokovanje.',
        6: 'Nasilno je odvzel svoje šotorsko svetišče, kakor če bi bil ta od vrta. Uničil je njegove kraje zborovanja. Gospod je storil, da se slovesni prazniki in šabate pozabijo v Sionu in v ogorčenju svoje jeze je preziral kralja in duhovnika.',
        7: 'Gospod je zavrgel svoj oltar, preziral svoje svetišče, zidove svoje palače je predal v roko sovražnika; v Gospodovi hiši so vzdignili hrup kakor na dan slovesnega praznika.',
        8: 'Gospod se je namenil, da uniči obzidje sionske hčere. Iztegnil je vrvico, svoje roke ni umaknil pred uničevanjem. Zato je naredil obrambni zid in obzidje za žalovanje; skupaj so slabeli.',
        9: 'Njena velika vrata so se pogreznila v tla; uničeni in zlomljeni so njeni zapahi. Njen kralj in njeni princi so med pogani. Postave ni več, tudi njeni preroki ne najdejo videnja od Gospoda.',
        10: 'Starešine hčere sionske sedijo na tleh in molčijo. Na svoje glave so metali prah. Opasali so se z vrečevino. Device [prestolnice] Jeruzalem svoje glave povešajo k tlom.',
        11: 'Moje oči pešajo s solzami, moja notranjost je vznemirjena, moja jetra so izlita na zemljo zaradi uničenja hčere mojega ljudstva; ker so otroci in dojenčki omedlevali na ulicah mesta.',
        12: 'Svojim materam pravijo: »Kje sta žito in vino?« ko so omedlevali kakor ranjeni na ulicah mesta, ko so bile njihove duše izlite v naročje njihovih mater.',
        13: 'Kakšno stvar bom vzel, da pričuje zate? S kakšno stvarjo te bom primerjal, oh hči [prestolnice] Jeruzalem? Kaj bom enačil s teboj, da bi te lahko potolažil, oh devica, hči sionska, kajti tvoja vrzel je velika kakor morje. Kdo te lahko ozdravi?',
        14: 'Tvoji preroki so zate videli prazne in bedaste stvari in niso odkrili tvoje krivičnosti, da odvrnejo tvoje ujetništvo, temveč so zate videli napačna bremena in razloge izgnanstva.',
        15: 'Vsi, ki gredo mimo, s svojimi rokami ploskajo nad teboj, sikajo in s svojimi glavami zmajujejo ob jeruzalemski hčeri, rekoč: »Ali je to mesto, ki ga ljudje imenujejo Popolnost lepote, Radost celotne zemlje?«',
        16: 'Vsi tvoji sovražniki so odprli svoja usta zoper tebe. Sikajo in škripajo z zobmi. Pravijo: »Požrli smo jo. Zagotovo, to je dan, ki smo se ga veselili; našli smo, videli smo to.',
        17: 'Gospod je storil to, kar je načrtoval. Izpolnil je svojo besedo, ki jo je zapovedal od dni davnine. Zrušil je in se ni usmilil in tvojemu sovražniku je dal, da se veseli nad teboj, vzdignil je rog tvojih nasprotnikov.',
        18: 'Njihovo srce je klicalo h Gospodu, oh obzidje hčere sionske, naj solze tečejo kakor reka, podnevi in ponoči. Ne daj si počitka, naj punčica tvojega očesa ne preneha.',
        19: 'Vstani, zavpij ponoči. Ob začetku straž izlij svoje srce kakor vodo pred Gospodovim obrazom. Dvigni svoje roke k njemu zaradi življenja svojih mladih otrok, ki slabijo zaradi lakote na vrhu vsake ulice.',
        20: 'Glej, oh Gospod in preudari, komu si to storil. Mar bodo ženske jedle svoj sad, otroke pedenj dolge? Mar bosta duhovnik in prerok umorjena v Gospodovem svetišču?',
        21: 'Mladi in stari ležijo po tleh na ulicah. Moje device in moji mladeniči so padli pod mečem; umoril si jih na dan svoje jeze, pobil si jih in se nisi usmilil.',
        22: 'Poklical si kakor na slovesen dan moje strahote naokoli, tako da na dan Gospodove jeze nihče ni pobegnil niti preostal. Tiste, ki sem jih povil in vzgojil, je použil moj sovražnik.',
    },
    3: {
        1: 'Jaz sem človek, ki je videl stisko s palico njegovega besa.',
        2: 'Vodil me je in me privedel v temo, toda ne v svetlobo.',
        3: 'Zagotovo je obrnjen zoper mene; svojo roko je obračal zoper mene ves dan.',
        4: 'Postaral je moje meso in mojo kožo, zlomil je moje kosti.',
        5: 'Zidal je zoper mene in me obdal z žolčem in muko.',
        6: 'Postavil me je v temne kraje, kakor tiste, ki so mrtvi od davnine.',
        7: 'Ogradil me je naokoli, da ne morem priti ven. Mojo verigo je naredil težko.',
        8: 'Tudi ko jokam in vpijem, on ustavlja mojo molitev.',
        9: 'Moje steze je obdal s klesanim kamnom, moje poti je storil sprijene.',
        10: 'Bil mi je kakor medved, ki preži v zasedi in kakor lev na skrivnih krajih.',
        11: 'Moje poti je obrnil vstran in me raztrgal. Naredil me je zapuščenega.',
        12: 'Upognil je svoj lok in me postavil kakor tarčo za puščico.',
        13: 'Puščicam svojega tula je storil, da vstopijo v mojo notranjost.',
        14: 'Bil sem v posmeh vsemu svojemu ljudstvu in ves dan njihova pesem.',
        15: 'Nasičeval me je z grenkobo, opijanjal me je s pelinom.',
        16: 'Prav tako je moje zobe zlomil z ostrimi kamni, pokril me je s pepelom.',
        17: 'Mojo dušo si odstranil daleč stran od miru. Pozabil sem uspevanje.',
        18: 'Rekel sem: »Moja moč in moje upanje je izginilo od Gospoda,',
        19: 'spominjajoč se moje stiske in moje bede, pelina in žolča.',
        20: 'Moja duša jih ima še vedno v spominu in je ponižana v meni.',
        21: 'To si ponovno kličem v svoj um, zato imam upanje.',
        22: 'To je od Gospodovih milosti, da nismo použiti, ker njegova sočutja ne odnehajo.',
        23: 'Ta so nova vsako jutro. Velika je tvoja zvestoba.',
        24: 'Gospod je moj delež, pravi moja duša, zato bom upal vanj.',
        25: 'Gospod je dober vsem tistim, ki čakajo nanj; duši, ki ga išče.',
        26: 'Dobro je, da bi človek upal in tiho čakal na Gospodovo rešitev duše.',
        27: 'Dobro je za človeka, da nosi jarem v svoji mladosti.',
        28: 'Sedi sam in molči, ker ga je nosil na sebi.',
        29: 'Svoja usta polaga v prah, morda bi bilo lahko še upanje.',
        30: 'Svoje lice daje tistemu, ki ga udarja, napolnjen je z grajo.',
        31: 'Kajti Gospod ne bo zavrgel na veke,',
        32: 'toda čeprav je povzročil žalost, bo vendar imel sočutje glede na množico svojih usmiljenj.',
        33: 'Kajti on ni voljan prizadeti niti užalostiti človeških otrok.',
        34: 'Da bi pod svojimi stopali zdrobil vse jetnike zemlje,',
        35: 'da bi odvrnil človekovo pravico pred obrazom Najvišjega,',
        36: 'da človeka spodkoplje v njegovi pravdi, [tega] Gospod ne odobrava.',
        37: 'Kdo je tisti, ki pravi in se to zgodi, ko Gospod tega ne zapove?',
        38: 'Iz ust Najvišjega ne izhaja zlo in dobro?',
        39: 'Zakaj se živeči človek pritožuje, človek zaradi kaznovanja svojih grehov?',
        40: 'Preiščimo in preizkusimo svoje poti in se ponovno obrnimo h Gospodu.',
        41: 'Vzdignimo svoja srca s svojimi rokami k Bogu v nebesih.',
        42: 'Pregrešili smo se in uprli. Ti nisi oprostil.',
        43: 'Pokril si [nas] s svojo jezo in nas preganjal. Umoril si, nisi se usmilil.',
        44: 'Pokril si se z oblakom, da naša molitev ne bi šla skozi.',
        45: 'Naredil si nas kakor izvržek in zavrnitev v sredi ljudstev.',
        46: 'Vsi naši sovražniki so odprli svoja usta zoper nas.',
        47: 'Strah in zanka sta prišla nad nas, opustošenje in uničenje.',
        48: 'Moje oko teče navzdol z rekami voda, zaradi uničenja hčere mojega ljudstva.',
        49: 'Moje oko se izliva in ne preneha, brez kakršnegakoli predaha,',
        50: 'dokler Gospod ne pogleda dol in ne pogleda iz nebes.',
        51: 'Moje oko prizadeva moje srce, zaradi vseh hčera mojega mesta.',
        52: 'Moji sovražniki so me boleče preganjali kakor ptico, brez vzroka.',
        53: 'Moje življenje so odsekali v grajski ječi in name vrgli kamen.',
        54: 'Vode so mi tekle čez glavo; potem sem rekel: »Odsekan sem.«',
        55: 'Klical sem k tvojemu imenu, oh Gospod, iz globine grajske ječe.',
        56: 'Slišal si moj glas. Ne skrivaj svojega ušesa ob mojem dihanju, ob mojem klicu.',
        57: 'Priteguješ me na dan, ko sem klical k tebi. Ti praviš: »Ne boj se.«',
        58: 'Oh Gospod, zagovarjal si pravde moje duše, odkupil si moje življenje.',
        59: 'Oh Gospod, videl si mojo krivico. Ti sodi mojo pravdo.',
        60: 'Videl si vse njihovo maščevanje in vse njihove zamisli zoper mene.',
        61: 'Slišal si njihovo grajo, oh Gospod in vse njihove zamisli zoper mene;',
        62: 'ustnice tistih, ki se vzdigujejo zoper mene in njihovo premišljevanje zoper mene ves dan.',
        63: 'Glej, njihovo usedanje in njihovo vzdigovanje; jaz sem njihova glasba.',
        64: 'Vrni jim povračilo, oh Gospod, glede na delo njihovih rok.',
        65: 'Daj jim bridkost srca, svoje prekletstvo nad njimi.',
        66: 'Preganjaj jih in jih uniči v jezi izpod Gospodovih nebes.',
    },
    4: {
        1: 'Kako je zlato postalo zatemnjeno! Kako se je najbolj čisto zlato spremenilo! Kamni svetišča so izliti na vrhu vsake ulice.',
        2: 'Dragoceni sionski sinovi, primerljivi čistemu zlatu, kako so cenjeni, kakor lončeni vrči, delo lončarjevih rok!',
        3: 'Celo morske pošasti iztegnejo prsi, dajejo piti svojim mladičem. Hči mojega ljudstva je postala kruta, podobna nojem v divjini.',
        4: 'Jezik doječega otroka se zaradi žeje lepi na nebo njegovih ust. Mladi otroci prosijo kruha, pa jim ga noben človek ne nalomi.',
        5: 'Tisti, ki so se prefinjeno hranili, so zapuščeni na ulicah. Tisti, ki so bili vzgojeni v škrlatu, objemajo gnojišča.',
        6: 'Kajti kazen krivičnosti hčere mojega ljudstva je večja kakor kazen za greh Sódome, ki je bila v hipu zrušena in nobene roke se je niso dotaknile.',
        7: 'Njeni nazirci so bili čistejši od snega, bolj so bili beli kakor mleko, po telesu so bili bolj rdečkasti kakor rubini, njihova gladkost je bila [podobna] safirju.',
        8: 'Njihov videz je bolj črn kakor oglje; na ulicah niso prepoznavni. Njihova koža se lepi na njihove kosti; izsušena je, postala je kakor palica.',
        9: 'Tisti, ki so umorjeni z mečem, so boljši kakor tisti, ki so umorjeni z lakoto, kajti ti hirajo, zadeti zaradi potrebe po poljskem sadu.',
        10: 'Roke sočutnih žensk so kuhale svoje lastne otroke. Bili so njihova hrana v uničenju hčere mojega ljudstva.',
        11: 'Gospod je dovršil svojo razjarjenost; izlil je svojo kruto jezo in prižgal ogenj na Sionu in ta je požrl njegove temelje.',
        12: 'Kralji zemlje in vsi prebivalci zemeljskega [kroga] niso hoteli verjeti, da bosta nasprotnik in sovražnik vstopila v velika vrata Jeruzalema.',
        13: 'Zaradi grehov njenih prerokov in krivičnosti njenih duhovnikov, ki so prelivali kri pravičnih v njeni sredi,',
        14: 'klatili so se kakor slepi možje po ulicah, oskrunili so se s krvjo, tako da se možje niso mogli dotakniti njihovih oblek.',
        15: 'Klicali so jim: »Odidite; to je nečisto; odidite, odidite, ne dotikajte se.« Ko so pobegnili in se potikali so med pogani govorili: »Nič več ne bodo začasno prebivali tam.',
        16: 'Gospodova jeza jih je razdelila; ne bo se več oziral nanje. Niso spoštovali oseb duhovnikov, niso bili naklonjeni starešinam.',
        17: 'Kar se tiče nas, so naše oči doslej odpovedovale zaradi naše prazne pomoči. V svojem oprezanju smo oprezali za narodom, ki nas ni mogel rešiti.',
        18: 'Lovijo naše korake, da ne moremo iti na svoje ulice. Naš konec je blizu, naši dnevi so izpolnjeni, kajti naš konec je prišel.',
        19: 'Naši preganjalci so hitrejši kakor orli neba. Zasledovali so nas po gorah, na nas so prežali v divjini.',
        20: 'Dih naših nosnic, Gospodov maziljenec, je bil odveden v njihove jame, o katerem smo rekli: »Pod njegovo senco bomo živeli med pogani.«',
        21: 'Razveseljuj se in bodi vesela, oh edómska hči, ki prebivaš v deželi Uc; prav tako bo čaša prešla k tebi. Opijanjena boš in razgalila se boš.',
        22: 'Kazen tvoje krivičnosti je dovršena, oh hči sionska; nič več te ne bo odvedel v ujetništvo. Obiskal bo tvojo krivičnost, oh hči edómska; odkril bo tvoje grehe.',
    },
    5: {
        1: 'Spomni se, oh Gospod, kaj je prišlo nad nas. Preudari in poglej našo grajo.',
        2: 'Naša dediščina je obrnjena k tujcem, naše hiše k neznancem.',
        3: 'Sirote smo in brez očeta, naše matere so kakor vdove.',
        4: 'Svojo vodo smo pili za denar; naš les nam je prodan.',
        5: 'Naši vratovi so pod preganjanjem. Trudimo se, pa nimamo počitka.',
        6: 'Roko smo izročili k Egipčanom in k Asircem, da bi bili nasičeni s kruhom.',
        7: 'Naši očetje so grešili in jih ni in mi smo nosili njihove krivičnosti.',
        8: 'Služabniki so vladali nad nami. Nikogar ni, da bi nas osvobodil iz njihove roke.',
        9: 'Svoj kruh smo prinašali z nevarnostjo za svoja življenja, zaradi meča iz divjine.',
        10: 'Naša koža je bila črna kakor peč zaradi strašne lakote.',
        11: 'Posiljevali so ženske na Sionu in device v Judovih mestih.',
        12: 'Z njihovo roko so obesili prince. Obrazi starešin niso bili spoštovani.',
        13: 'Zajeli so mladeniče, da meljejo in otroci so padali pod lesom.',
        14: 'Starešine so odšli od velikih vrat, mladeniči od svoje glasbe.',
        15: 'Veselje našega srca je prenehalo, naš ples je obrnjen v žalovanje.',
        16: 'Krona je padla iz naše glave. Gorje nam, da smo grešili!',
        17: 'Zaradi tega peša naše srce, zaradi teh stvari so zatemnjene naše oči.',
        18: 'Zaradi gore Sion, ki je zapuščena, lisice hodijo po njej.',
        19: 'Ti, oh Gospod, ostajaš na veke, tvoj prestol od roda do roda.',
        20: 'Zakaj nas pozabljaš na veke in nas zapuščaš za tako dolgo?',
        21: 'Obrni nas k sebi, oh Gospod in mi bomo obrnjeni; obnovi naše dni kakor od davnine.',
        22: 'Toda popolnoma si nas zavrgel. Zelo si ogorčen zoper nas.',
    },
}
